        assert!(!scrubbed.contains("xoxp-"));
    }

    #[test]
    fn scrub_removes_long_hex_strings() {
        let input = "hash: aabbccddeeff00112233445566778899";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("aabbccddeeff"));
    }

    #[test]
    fn scrub_handles_multiple_sensitive_items() {
        let input = "Error at /Users/brenna/proj: ghp_abcdefghijklmnopqrstuvwxyz1234567890 failed";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("/Users/brenna"));
        assert!(!scrubbed.contains("ghp_"));
    }

    #[test]
    fn scrub_does_not_mask_non_secret_env_vars() {
        let mut env = HashMap::new();
        env.insert("RAILS_ENV".to_string(), "production".to_string());

        let input = "Running in production mode";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, input, "Non-secret env var values should not be masked");
    }

    #[test]
    fn scrub_masks_multiple_secret_env_vars() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "key-aaa".to_string());
        env.insert("SECRET_TOKEN".to_string(), "tok-bbb".to_string());

        let input = "Auth failed: key-aaa and tok-bbb rejected";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(!scrubbed.contains("key-aaa"), "First secret should be masked");
        assert!(!scrubbed.contains("tok-bbb"), "Second secret should be masked");
    }

    #[test]
    fn scrub_skips_empty_env_values() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "Some normal text";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, input, "Empty env values should not affect output");
    }

    #[test]
    fn scrub_truncation_boundary() {
        // Exactly MAX_ERROR_LENGTH chars should NOT be truncated
        let input = "x".repeat(MAX_ERROR_LENGTH);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
        assert!(!scrubbed.contains("...[truncated]"));
    }

    #[test]
    fn scrub_truncation_one_over() {
        // MAX_ERROR_LENGTH + 1 chars should be truncated
        let input = "x".repeat(MAX_ERROR_LENGTH + 1);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert!(scrubbed.ends_with("...[truncated]"));
    }

    // --- build_report edge cases ---

    #[test]
    fn build_report_with_none_exit_code() {
        let report = build_report("test", "cmd", None, "err", "retry", &HashMap::new());
        assert_eq!(report.exit_code, None);
    }

    #[test]
    fn build_report_scrubs_command() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "secret123".to_string());

        let report = build_report(
            "deploy",
            "curl -H 'Authorization: secret123' http://example.com",
            Some(1),
            "",
            "retry",
            &env,
        );

        assert!(!report.command_scrubbed.contains("secret123"));
    }

    #[test]
    fn build_report_scrubs_error_output() {
        let report = build_report(
            "test",
            "make",
            Some(2),
            "Error at /Users/dev/project/main.c:10",
            "fix",
            &HashMap::new(),
        );

        assert!(!report.error_scrubbed.contains("/Users/dev"));
        assert!(report.error_scrubbed.contains("[PATH]"));
    }

    #[test]
    fn build_report_platform_format() {
        let report = build_report("t", "c", None, "", "r", &HashMap::new());
        // Platform should be "os-arch" format
        assert!(report.platform.contains('-'), "Platform should be os-arch: {}", report.platform);
        assert_eq!(
            report.platform,
            format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH)
        );
    }

    // --- prompt_telemetry edge cases ---

    #[test]
    fn telemetry_prompt_returns_always() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
    }

    #[test]
    fn telemetry_prompt_returns_never() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_response_defaults_to_no_thanks() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "something_unknown");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }

    #[test]
    fn telemetry_prompt_unknown_saved_preference_still_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        assert_eq!(ui.prompts_shown().len(), 1, "Should show the prompt for unknown preference");
    }

    #[test]
    fn telemetry_prompt_shows_step_name_in_messages() {
        let report = build_report(
            "my_step",
            "bundle install",
            Some(1),
            "some error",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("my_step"), "Step name should appear in messages");
        assert!(ui.has_message("bundle install"), "Command should appear in messages");
        assert!(ui.has_message("some error"), "Error should appear in messages");
        assert!(
            ui.has_message("shell → retry"),
            "Recovery action should appear in messages"
        );
    }

    #[test]
    fn telemetry_prompt_shows_exit_code() {
        let report = build_report("step", "cmd", Some(42), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("42"), "Exit code should appear in messages");
    }

    #[test]
    fn telemetry_prompt_skips_empty_error() {
        let report = build_report("step", "cmd", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let error_lines: Vec<_> = ui.messages().iter().filter(|m| m.contains("Error:")).collect();
        assert!(error_lines.is_empty(), "Empty error should not be shown");
    }

    #[test]
    fn telemetry_prompt_skips_none_exit_code() {
        let report = build_report("step", "cmd", None, "err", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let exit_lines: Vec<_> = ui.messages().iter().filter(|m| m.contains("Exit:")).collect();
        assert!(exit_lines.is_empty(), "None exit code should not show Exit line");
    }

    // --- save_report_to ---

    #[test]
    fn save_report_creates_directory() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("deep").join("nested");
        let report = build_report("test", "cmd", Some(0), "err", "retry", &HashMap::new());

        let path = save_report_to(&report, &nested).unwrap();
        assert!(path.exists());
        assert!(nested.is_dir());
    }

    #[test]
    fn save_report_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("my_bundler", "cmd", Some(0), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_str().unwrap();
        assert!(
            filename.contains("my_bundler"),
            "Filename should contain step name: {}",
            filename
        );
        assert!(filename.ends_with(".yml"), "Filename should end with .yml: {}", filename);
    }

    #[test]
    fn save_report_roundtrip_yaml() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "linking failed",
            "shell → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, "cargo");
        assert_eq!(loaded.command_scrubbed, "cargo build");
        assert_eq!(loaded.exit_code, Some(101));
        assert_eq!(loaded.error_scrubbed, "linking failed");
        assert_eq!(loaded.recovery_action, "shell → retry");
        assert_eq!(loaded.bivvy_version, report.bivvy_version);
        assert_eq!(loaded.platform, report.platform);
    }

    #[test]
    fn save_report_roundtrip_none_exit_code() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("step", "cmd", None, "err", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.exit_code, None);
    }

    // --- reports_dir ---

    #[test]
    fn reports_dir_ends_with_failure_reports() {
        let dir = reports_dir();
        assert!(
            dir.ends_with("failure-reports"),
            "reports_dir should end with failure-reports: {:?}",
            dir
        );
        assert!(
            dir.to_str().unwrap().contains(".bivvy"),
            "reports_dir should be under .bivvy: {:?}",
            dir
        );
    }

    // --- FailureReport serialization ---

    #[test]
    fn failure_report_serialize_deserialize() {
        let report = FailureReport {
            step_name: "test_step".to_string(),
            command_scrubbed: "make build".to_string(),
            exit_code: Some(2),
            error_scrubbed: "build failed".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "0.1.0".to_string(),
            platform: "macos-aarch64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(loaded.step_name, report.step_name);
        assert_eq!(loaded.command_scrubbed, report.command_scrubbed);
        assert_eq!(loaded.exit_code, report.exit_code);
        assert_eq!(loaded.error_scrubbed, report.error_scrubbed);
        assert_eq!(loaded.recovery_action, report.recovery_action);
        assert_eq!(loaded.bivvy_version, report.bivvy_version);
        assert_eq!(loaded.platform, report.platform);
    }

    #[test]
    fn telemetry_prompt_default_falls_back_to_no_thanks() {
        let report = build_report("test", "echo hi", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        // Don't set any prompt response — the default in the prompt is "no_thanks"

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }
}

