    #[test]
    fn scrub_removes_tokens() {
        let input = "Error: auth failed with token ghp_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(
            scrubbed.contains("[REDACTED]"),
